'use client';

import { useEffect, useState } from 'react';
import styles from './hero.module.css';

const PHRASES = ['Ownership Driven', 'Without Hiring', 'On Demand'];
const TYPE_SPEED = 80;
const DELETE_SPEED = 50;
const PAUSE_MS = 2000;

export default function Typewriter() {
  const [displayed, setDisplayed] = useState('');
  const [phraseIndex, setPhraseIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    const current = PHRASES[phraseIndex];

    if (!deleting && charIndex < current.length) {
      const t = setTimeout(() => setCharIndex((c) => c + 1), TYPE_SPEED);
      return () => clearTimeout(t);
    }

    if (!deleting && charIndex === current.length) {
      const t = setTimeout(() => setDeleting(true), PAUSE_MS);
      return () => clearTimeout(t);
    }

    if (deleting && charIndex > 0) {
      const t = setTimeout(() => setCharIndex((c) => c - 1), DELETE_SPEED);
      return () => clearTimeout(t);
    }

    if (deleting && charIndex === 0) {
      setDeleting(false);
      setPhraseIndex((i) => (i + 1) % PHRASES.length);
    }
  }, [charIndex, deleting, phraseIndex]);

  useEffect(() => {
    setDisplayed(PHRASES[phraseIndex].slice(0, charIndex));
  }, [charIndex, phraseIndex]);

  return (
    <span className={styles['animate-span']}>
      {displayed}
      <span aria-hidden="true" style={{ borderRight: '2px solid #05bafe', marginLeft: '2px', animation: 'blink 1s step-end infinite' }} />
    </span>
  );
}

