import Image from 'next/image';
import styles from './featured-logos.module.css';

const LOGOS = [
  {
    src: '/images/webflow/68ef9013b2a3f77a6fe65a0d_image-234.svg',
    alt: 'forbes logo',
    width: 100,
    height: 32,
  },
  {
    src: '/images/webflow/68ef9013ae41bcbd0914ef6a_image-235.svg',
    alt: 'Entrepreneur logo',
    width: 140,
    height: 32,
  },
  {
    src: '/images/webflow/68ef90122cc026bc542ca992_image-236.svg',
    alt: 'Inc. Logo',
    width: 60,
    height: 32,
  },
  {
    src: '/images/webflow/68ef90124d939b1501f73e75_image-237.svg',
    alt: 'The washington post logo',
    width: 180,
    height: 32,
  },
  {
    src: '/images/webflow/68ef901324f4b0506dab4aa7_image-239.svg',
    alt: 'Philadelphia logo',
    width: 130,
    height: 32,
  },
  {
    src: '/images/webflow/68ef90139f3536c7615bc0d3_image-240.svg',
    alt: 'Technically logo',
    width: 120,
    height: 32,
  },
] as const;

// Duplicated for seamless infinite scroll
const ALL_LOGOS = [...LOGOS, ...LOGOS];

export function FeaturedLogos() {
  return (
    <section
      className={`${styles['section-regular']} ${styles['no-padding-mob']} ${styles['logo-mob']}`}
    >
      {/* "Featured in:" label */}
      <div className={styles['logo-3-title']}>
        <p className={`${styles['paragraph-x-large']} ${styles['text-color-secondary']}`}>
          Featured in:
        </p>
      </div>

      {/* Infinite scroll carousel */}
      <div className={styles['logo-3-carousel']}>
        <div className={styles['logo-3-content']} style={{ animation: 'logo-scroll 40s linear infinite', width: 'max-content' }}>
          {ALL_LOGOS.map((logo, i) => (
            <div key={i} className={styles['logo-3-block']}>
              <Image
                src={logo.src}
                alt={logo.alt}
                width={logo.width}
                height={logo.height}
                loading="lazy"
                className={styles['logo-3-icon']}
                style={{ objectFit: 'contain' }}
              />
            </div>
          ))}
        </div>
      </div>

      <style>{`
        @keyframes logo-scroll {
          0% { transform: translateX(0); }
          100% { transform: translateX(-50%); }
        }
        @media (prefers-reduced-motion: reduce) {
          .logo-scroll-track { animation: none !important; }
        }
      `}</style>
    </section>
  );
}

/* ============================================================
   PORTFOLIO CAROUSEL — portfolio-carousel.module.css
   Extracted verbatim from boldteq-v1-0.webflow.css
   ============================================================ */

.section-regular-2 {
  background-color: #fff;
  padding: 64px 15% 64px 2%;
  position: relative;
  overflow: hidden;
}

.img-slider-sec {
  padding-top: 20px;
  padding-right: 0%;
}

.column-4x-large {
  grid-column-gap: 80px;
  grid-row-gap: 80px;
  flex-flow: column;
  display: flex;
}

/* Slider wrapper */
.gallery-13-slider {
  background-color: #0000;
  height: auto;
  padding-bottom: 0;
  position: relative;
  width: 100%;
}

.gallery-13-mask {
  max-width: none;
  height: auto;
  overflow: hidden;
  display: flex;
}

.gallery-13-slide {
  max-width: calc(25% - 12px);
  height: 100%;
  margin-right: 24px;
  flex-shrink: 0;
}

/* Cards */
.gallery-13-card {
  aspect-ratio: 1 / 1.25;
  border: 1px #000;
  border-radius: 20px;
  width: 100%;
  min-height: 392px;
  padding: 10px;
  position: relative;
  overflow: hidden;
}

.cream {
  aspect-ratio: 1 / 1.22;
  background-color: #fbf2e4;
  border-style: none;
  min-height: auto;
  padding: 10px;
}

.light-green {
  aspect-ratio: 1 / 1.22;
  background-color: #e6fccd;
  border-style: none;
  min-height: auto;
  padding: 10px;
}

.light-purple {
  aspect-ratio: 1 / 1.22;
  background-color: #4da1af1a;
  border-style: none;
  min-height: auto;
  padding: 10px;
}

.light-orange {
  aspect-ratio: 1 / 1.22;
  background-color: #ff8a8a14;
  border-style: none;
  min-height: auto;
  padding: 10px;
}

/* Image outer wrapper */
.gallery-image-outer {
  border-radius: 15px;
  margin-bottom: 20px;
  padding-top: 20px;
  padding-left: 20px;
  padding-right: 20px;
}

.green {
  background-color: #0d4a4c;
  min-height: auto;
}

.green-light {
  background-color: #abf330;
  height: auto;
  min-height: auto;
}

.orange-light {
  background-color: #ffc671;
  min-height: auto;
}

.olive-green {
  background-color: #5e6350;
  min-height: auto;
}

/* The portfolio image */
.image-cover {
  object-fit: cover;
  object-position: 50% 0%;
  border-radius: 10px;
  width: 100%;
  height: auto;
  min-height: auto;
  max-height: 357px;
  display: block;
  position: relative;
  overflow: hidden;
}

.radius-0 {
  border-radius: 0;
}

/* Caption */
.gallery-13-caption {
  text-align: left;
  background-color: #0000;
  border-radius: 8px;
  height: auto;
  padding: 0;
  position: relative;
  inset: auto;
  overflow: visible;
}

.heading-3 {
  color: #082753;
  text-align: left;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 25px;
  font-weight: 700;
}

/* Color variants for heading-3 */
.heading-3-green,
.heading-3-green-light,
.heading-3-purple {
  color: #020e41;
  text-align: center;
  font-size: 1.3rem;
}

.heading-3-orange {
  color: #111c19;
  text-align: center;
  -webkit-text-stroke-color: #ff8a8a;
  font-size: 1.3rem;
}

/* Nav buttons */
.gallery-13-button {
  width: auto;
  position: absolute;
  inset: auto 0% 0% auto;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
}

.button-left {
  left: -1.5%;
  right: auto;
}

.button-right {
  right: 0.5%;
}

.icon-button-outline-large {
  color: #000;
  background-color: #fff;
  border: 1px solid #c9d2d9;
  border-radius: 11px;
  flex: none;
  justify-content: center;
  align-items: center;
  width: 48px;
  height: 48px;
  display: flex;
  cursor: pointer;
}

.icon-regular {
  width: 24px;
  height: 24px;
  flex: none;
  justify-content: center;
  align-items: center;
  display: flex;
}

.icon-blue {
  color: #21cfff;
}

.container-large-2 {
  z-index: 1;
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
  position: relative;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .section-regular-2.img-slider-sec {
    padding-right: 0%;
  }

  .gallery-13-button.button-right {
    right: 0.5%;
  }

  .image-cover {
    height: 360px;
  }

  .image-cover.radius-0 {
    height: auto;
  }

  .gallery-13-slide {
    min-height: 392px;
  }

  .gallery-13-mask {
    height: auto;
  }

  .gallery-13-card.cream,
  .gallery-13-card.light-green,
  .gallery-13-card.light-purple,
  .gallery-13-card.light-orange {
    aspect-ratio: 1 / 1.2;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .section-regular-2 {
    max-width: none;
    padding-right: 22%;
  }

  .section-regular-2.img-slider-sec {
    max-width: none;
    padding-right: 0%;
  }

  .gallery-13-button.button-right {
    right: 0.5%;
  }

  .image-cover {
    object-fit: cover;
    height: 410px;
    min-height: auto;
    max-height: 420px;
    position: static;
  }

  .image-cover.radius-0 {
    height: auto;
  }

  .gallery-13-slider {
    align-self: auto;
    max-width: none;
  }

  .gallery-13-slide {
    height: 100%;
    min-height: 392px;
    position: static;
  }

  .gallery-13-mask {
    height: auto;
  }

  .gallery-13-card.cream,
  .gallery-13-card.light-green,
  .gallery-13-card.light-purple,
  .gallery-13-card.light-orange {
    aspect-ratio: auto;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .section-regular-2.img-slider-sec {
    padding-right: 2%;
  }

  .gallery-13-button.button-left {
    left: -1%;
  }

  .gallery-13-button.button-right {
    right: -1%;
  }

  .column-4x-large {
    grid-column-gap: 64px;
    grid-row-gap: 64px;
  }

  .gallery-13-slide {
    max-width: calc(50% - 12px);
  }

  .gallery-13-mask {
    max-width: none;
    height: auto;
  }

  .gallery-13-card.cream,
  .gallery-13-card.light-green,
  .gallery-13-card.light-purple,
  .gallery-13-card.light-orange {
    aspect-ratio: auto;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .column-4x-large {
    grid-column-gap: 40px;
    grid-row-gap: 40px;
  }

  .gallery-13-slide {
    max-width: calc(50% - 12px);
  }

  .gallery-13-mask {
    max-width: none;
    height: auto;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section-regular-2.img-slider-sec {
    padding-top: 40px;
    padding-bottom: 50px;
  }

  .gallery-13-button.button-left {
    left: -2.5%;
  }

  .gallery-13-slide {
    max-width: calc(100% - 12px);
    height: 100%;
    margin-right: 15px;
  }

  .gallery-13-mask {
    max-width: none;
    height: auto;
  }

  .heading-3 {
    font-size: 22px;
    line-height: 26px;
  }
}

