'use client';

import Image from 'next/image';
import { useCallback, useEffect, useState } from 'react';
import useEmblaCarousel from 'embla-carousel-react';
import styles from './portfolio-carousel.module.css';

interface Slide {
  label: string;
  labelVariant: string;
  cardVariant: string;
  imageOuterVariant: string;
  imageSrc: string;
  imageAlt: string;
  imageWidth: number;
  imageHeight: number;
}

const SLIDES: Slide[] = [
  {
    label: 'Shopify',
    labelVariant: 'heading-3-green',
    cardVariant: 'cream',
    imageOuterVariant: 'green',
    imageSrc: '/images/webflow/69662a202a4c0d57bdf2c10b_Home.png',
    imageAlt: 'Portfolio Image',
    imageWidth: 843,
    imageHeight: 690,
  },
  {
    label: 'WordPress',
    labelVariant: 'heading-3-green-light',
    cardVariant: 'light-green',
    imageOuterVariant: 'green-light',
    imageSrc: '/images/webflow/Travel.png',
    imageAlt: 'TravelPerk corporate travel management website template built by Boldteq',
    imageWidth: 840,
    imageHeight: 690,
  },
  {
    label: 'Figma UI/UX Design',
    labelVariant: 'heading-3-purple',
    cardVariant: 'light-purple',
    imageOuterVariant: 'orange-light',
    imageSrc: '/images/webflow/Home-1.png',
    imageAlt: 'Dynamic lifestyle brand website template built by Boldteq',
    imageWidth: 843,
    imageHeight: 690,
  },
  {
    label: 'Banners',
    labelVariant: 'heading-3-orange',
    cardVariant: 'light-orange',
    imageOuterVariant: 'olive-green',
    imageSrc: '/images/webflow/Group-7.png',
    imageAlt: 'Beauty and skincare product website template built by Boldteq',
    imageWidth: 807,
    imageHeight: 690,
  },
];

// Duplicate for seamless loop
const ALL_SLIDES = [...SLIDES, ...SLIDES];

export function PortfolioCarousel() {
  const [emblaRef, emblaApi] = useEmblaCarousel({
    loop: true,
    align: 'start',
    dragFree: false,
    slidesToScroll: 1,
  });
  const [selectedIndex, setSelectedIndex] = useState(0);

  const scrollPrev = useCallback(() => emblaApi?.scrollPrev(), [emblaApi]);
  const scrollNext = useCallback(() => emblaApi?.scrollNext(), [emblaApi]);
  const scrollTo = useCallback((i: number) => emblaApi?.scrollTo(i), [emblaApi]);

  useEffect(() => {
    if (!emblaApi) return;
    const onSelect = () => setSelectedIndex(emblaApi.selectedScrollSnap() % SLIDES.length);
    emblaApi.on('select', onSelect);
    onSelect();
    return () => { emblaApi.off('select', onSelect); };
  }, [emblaApi]);

  return (
    <section
      className={`${styles['section-regular-2']} ${styles['img-slider-sec']}`}
    >
      <div className={styles['column-4x-large']} style={{ alignItems: 'center' }}>
        {/* Slider container — relative for arrow positioning */}
        <div style={{ position: 'relative', width: '100%' }}>
          {/* Embla viewport */}
          <div ref={emblaRef} className={styles['gallery-13-mask']}>
            {/* Track */}
            <div style={{ display: 'flex', gap: '24px', height: 'auto' }}>
              {ALL_SLIDES.map((slide, i) => (
                <div
                  key={`${slide.label}-${i}`}
                  className={styles['gallery-13-slide']}
                >
                  <div
                    className={`${styles['gallery-13-card']} ${styles[slide.cardVariant]}`}
                  >
                    {/* Image outer */}
                    <div
                      className={`${styles['gallery-image-outer']} ${styles[slide.imageOuterVariant]}`}
                    >
                      <Image
                        src={slide.imageSrc}
                        alt={slide.imageAlt}
                        width={slide.imageWidth}
                        height={slide.imageHeight}
                        loading="lazy"
                        className={`${styles['image-cover']} ${styles['radius-0']}`}
                      />
                    </div>
                    {/* Caption */}
                    <div className={styles['gallery-13-caption']}>
                      <div className={`${styles['heading-3']} ${styles[slide.labelVariant]}`}>
                        {slide.label}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Prev button */}
          <button
            onClick={scrollPrev}
            aria-label="Previous slide"
            className={`${styles['gallery-13-button']} ${styles['button-left']}`}
            style={{ background: 'none', border: 'none', padding: 0, cursor: 'pointer' }}
          >
            <div className={styles['icon-button-outline-large']}>
              <span className={`${styles['icon-regular']} ${styles['icon-blue']}`}>
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M7.82843 10.9999H20V12.9999H7.82843L13.1924 18.3638L11.7782 19.778L4 11.9999L11.7782 4.22168L13.1924 5.63589L7.82843 10.9999Z" fill="currentColor" />
                </svg>
              </span>
            </div>
          </button>

          {/* Next button */}
          <button
            onClick={scrollNext}
            aria-label="Next slide"
            className={`${styles['gallery-13-button']} ${styles['button-right']}`}
            style={{ background: 'none', border: 'none', padding: 0, cursor: 'pointer' }}
          >
            <div className={styles['icon-button-outline-large']}>
              <span className={`${styles['icon-regular']} ${styles['icon-blue']}`}>
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M16.1716 10.9999L10.8076 5.63589L12.2218 4.22168L20 11.9999L12.2218 19.778L10.8076 18.3638L16.1716 12.9999H4V10.9999H16.1716Z" fill="currentColor" />
                </svg>
              </span>
            </div>
          </button>
        </div>

        {/* Dot navigation */}
        <div
          style={{
            justifyContent: 'flex-start',
            alignItems: 'center',
            maxWidth: 'calc(100% - 112px)',
            marginLeft: 0,
            paddingTop: '16px',
            paddingBottom: '16px',
            display: 'flex',
            gap: '4px',
          }}
        >
          {SLIDES.map((_, i) => (
            <button
              key={i}
              onClick={() => scrollTo(i)}
              aria-label={`Go to slide ${i + 1}`}
              style={{
                height: '12px',
                width: '12px',
                borderRadius: '50%',
                border: 'none',
                cursor: 'pointer',
                transition: 'background-color 0.2s',
                backgroundColor: i === selectedIndex ? '#000' : '#EDF0F2',
                marginBottom: 0,
                padding: 0,
                flexShrink: 0,
              }}
            />
          ))}
        </div>
      </div>

      <div className={styles['container-large-2']} />
    </section>
  );
}

/* ============================================================
   PAIN POINTS — pain-points.module.css
   Extracted verbatim from boldteq-v1-0.webflow.css
   ============================================================ */

.section-regular-3 {
  -webkit-text-fill-color: inherit;
  background-color: #0000;
  background-clip: border-box;
  padding: 0 5% 80px;
  position: relative;
}

.slowing-sec {
  padding-bottom: 30px;
}

.container-large-3 {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

.heading-2 {
  color: var(--blue, #082753);
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: var(--h2, 40px);
  text-align: center;
  line-height: 40px;
}

.margin-bottom-24px {
  margin-bottom: 20px;
  font-size: 40px;
  line-height: 45px;
}

.paragraph {
  color: #2b2b2b;
  text-align: center;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
}

.center {
  text-align: center;
}

.feature-grid {
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
}

.margin-top-40px {
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  margin-top: 40px;
}

.agency-grid {
  /* no additional base rules — modifier class */
}

.feature-card {
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  text-align: center;
  mix-blend-mode: normal;
  background-color: #def4ff;
  background-image: none;
  border: 1px solid #009ce0;
  border-radius: 20px;
  flex-flow: column;
  justify-content: flex-start;
  align-items: center;
  padding: 25px 17px 17px;
  text-decoration: none;
  display: flex;
}

.text-wrapper {
  /* wrapper for text content inside feature card */
}

.featured-card-twrapper {
  /* modifier — no extra base CSS in Webflow source */
}

.subheading-large {
  color: #082753;
  letter-spacing: -0.02em;
  margin-bottom: 10px;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 25px;
}

.margin-bottom-5 {
  color: #082753;
  margin-bottom: 5px;
  font-size: 22px;
  line-height: 35px;
}

.paragraph-small-2 {
  color: #2b2b2b;
  min-height: auto;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: var(--para-small, 16px);
  letter-spacing: -0.08px;
  margin-bottom: 0;
  line-height: 24px;
}

.margin-bottom-20px {
  color: #2b2b2b;
  margin-bottom: 20px;
  font-size: 16px;
  line-height: 28px;
}

.full-width-image {
  width: 100%;
  max-width: 3768px;
}

.drop-shadow {
  max-width: 1492px;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .container-large-3,
  .container-large-3.full-width {
    max-width: 1280px;
  }

  .feature-card {
    background-color: #def4ff;
    border-color: #009ce0;
  }

  .feature-card.space-between {
    padding-left: 20px;
    padding-right: 20px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .section-regular-3.center-sec {
    padding-bottom: 0%;
  }

  .container-large-3 {
    max-width: 1280px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .feature-grid {
    grid-template-columns: 1fr;
  }

  .feature-grid.margin-top-40px {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .section-regular-3 {
    padding-bottom: 0;
  }

  .heading-2.margin-bottom-24px {
    margin-top: 0;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section-regular-3 {
    padding-top: 0;
    padding-bottom: 0;
  }

  .heading-2 {
    font-size: 34px;
  }

  .heading-2.margin-bottom-24px {
    font-size: 35px;
    line-height: 45px;
  }

  .feature-grid.margin-top-40px {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section-regular-3 {
    padding-top: 0;
    padding-bottom: 40px;
  }

  .heading-2.margin-bottom-24px {
    text-align: center;
    margin-bottom: 10px;
    font-size: 23px;
    line-height: 28px;
  }

  .paragraph.center {
    text-align: center;
  }

  .paragraph-small-2.margin-bottom-20px,
  .subheading-large,
  .subheading-large.margin-bottom-5 {
    text-align: center;
  }

  .feature-card {
    padding: 24px;
  }
}

